head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > checkAll]<br/>Body Column 의 ID 또는 인덱스값을 사용하여 전체 Body Cell 을 일괄 체크하거나 해제합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 일괄 체크/해제할 Body Column 의 Column ID 를 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="columnInfo 파라미터에 checkbox Column 의 ID(chk)를 설정하여 전체 Body Cell 을 일괄 체크/해제합니다. chk : checkbox(trueValue=1 / falseValue=0)."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chk  : checkbox 컬럼 원본값(1/0) - checkAll 대상
    // - name / dept : 일반 text 컬럼
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 초기 체크 상태를 혼합(1/0/1/0)으로 두어 토글/체크/해제 변화를 명확히 확인
    let jsonData = [
        { "chk": "1", "name": "John", "dept": "Sales" },
        { "chk": "0", "name": "Jane", "dept": "Dev"   },
        { "chk": "1", "name": "Mike", "dept": "Sales" },
        { "chk": "0", "name": "Amy",  "dept": "Dev"   }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 3컬럼 - 체크 / 이름 / 부서)
    // - chk : inputType="checkbox" trueValue="1" falseValue="0" (checkAll 대상)
    // - 마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:480px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="checkAll 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="체크"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // chk : checkbox 컬럼 (trueValue=1 / falseValue=0) - checkAll 대상
    strTarget += '<w2:column width="120" style="" inputType="checkbox" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 전체 Cell 의 현재 체크 상태(Column 의 셀 값)를 바인딩 DataList 에서 조회 -> 배열로 반환
scwin.getCheckStates = function (colId) {
    let len = dlt_bind.getRowCount();
    let states = [];
    for (let i = 0; i < len; i++) {
        states.push(dlt_bind.getCellData(i, colId));
    }
    return states;
}



// checkAll 확인 : par_columnInfo(Column ID) + par_data 로 호출 -> 전체 Body Cell 체크/해제/토글
// - data 1/true/trueValue : 전체 체크   -> 모든 셀 trueValue("1")
// - data 0/false/falseValue : 전체 해제 -> 모든 셀 falseValue("0")
// - data undefined/미해당 : 토글        -> 각 셀 현재값 반전
scwin.btn_checkAll_onclick = function () {
    let colId = par_columnInfo.getValue();
    let dataSel = par_data.getValue();

    // par_data 가 "undefined" 면 인자 자체를 생략하여 토글(기본 동작) 확인
    let dataValue;
    let callDesc;
    if (dataSel === "undefined") {
        target1.checkAll(colId);
        callDesc = "checkAll('" + colId + "')";
    } else {
        if (dataSel === "true") {
            dataValue = true;
        } else if (dataSel === "false") {
            dataValue = false;
        } else {
            // "1" / "0" 는 숫자로 전달
            dataValue = Number(dataSel);
        }
        target1.checkAll(colId, dataValue);
        callDesc = "checkAll('" + colId + "', " + dataValue + ")";
    }

    let states = scwin.getCheckStates(colId);
    wf_body_bottom.getObj("scwin").setReturnValue(callDesc + " -> '" + colId + "' Column 셀 체크상태 : " + JSON.stringify(states));
}
